// Mock HubSpot/Salesforce CRM contact sync
const body = items[0].json.body || items[0].json;
const campaignName = body.campaign_name || 'Generic Campaign';
const syncedContacts = (body.audiences || ['General B2B Segment']).length * 25;

return [{
  json: {
    execution_id: body.execution_id,
    crm_provider: 'HubSpot_Mock',
    campaign_name: campaignName,
    synced_contacts: syncedContacts,
    synced_at: new Date().toISOString()
  }
}];
